	public InsurancePayer updateInsurancePayer( UpdateInsurancePayerCommand command ) {

		InsurancePayer entity = new InsurancePayer();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setInsurancePayerId( command.getInsurancePayerId() );
            entity.setName( command.getName() );
            entity.setWebsite( command.getWebsite() );
            entity.setPlans( command.getPlans() );
            entity.setClaims( command.getClaims() );
            entity.setPayerType( command.getPayerType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of InsurancePayer {0} ", entity.toString() );

		return entity;
	}

